'use client'

import * as React from 'react'
import VisuallyHidden from '@radui/ui/VisuallyHidden'

import { useOffscreen } from './use-reduced-motion'
import './glitch-text.css'

type GlitchTag = 'p' | 'span' | 'div' | 'h1' | 'h2' | 'h3' | 'h4'

export type GlitchTextProps = {
    text: string
    as?: GlitchTag
    /** Seconds between glitch bursts. Each burst is brief and never flashes more than 3 times a second. */
    interval?: number
    /** Colours of the two split channels. */
    colors?: [string, string]
    paused?: boolean
    className?: string
}

const GlitchText = ({ text, as: Tag = 'span', interval = 3, colors = ['#22d3ee', '#f472b6'], paused = false, className }: GlitchTextProps) => {
    const ref = React.useRef<HTMLElement | null>(null)
    const offscreen = useOffscreen(ref)

    return <Tag
        ref={ref as React.Ref<never>}
        className={['rad-fx-glitch', className].filter(Boolean).join(' ')}
        data-state={paused || offscreen ? 'paused' : 'running'}
        style={{ '--rad-fx-glitch-interval': `${interval}s`, '--rad-fx-glitch-a': colors[0], '--rad-fx-glitch-b': colors[1] } as React.CSSProperties}
    >
        <VisuallyHidden asChild><span>{text}</span></VisuallyHidden>
        {/* Real elements rather than ::before/::after with content: attr(),
            which some screen readers read aloud. */}
        <span className="rad-fx-glitch-stack" aria-hidden="true">
            <span className="rad-fx-glitch-base">{text}</span>
            <span className="rad-fx-glitch-layer" data-channel="a">{text}</span>
            <span className="rad-fx-glitch-layer" data-channel="b">{text}</span>
        </span>
    </Tag>
}

export default GlitchText

.rad-fx-glitch-stack {
    position: relative;
    display: inline-block;
}

.rad-fx-glitch-layer {
    position: absolute;
    inset: 0;
    pointer-events: none;
    opacity: 0;
    animation: rad-fx-glitch-a var(--rad-fx-glitch-interval, 3s) steps(1) infinite;
}

.rad-fx-glitch-layer[data-channel='a'] { color: var(--rad-fx-glitch-a); }
.rad-fx-glitch-layer[data-channel='b'] { color: var(--rad-fx-glitch-b); animation-name: rad-fx-glitch-b; }

.rad-fx-glitch[data-state='paused'] .rad-fx-glitch-layer { animation-play-state: paused; opacity: 0; }

/* Quiet for most of the cycle, then a short burst of offset slices near the end. */
@keyframes rad-fx-glitch-a {
    0%, 88%, 100% { opacity: 0; transform: none; clip-path: none; }
    89% { opacity: 0.9; transform: translate(-3px, 1px); clip-path: inset(10% 0 55% 0); }
    92% { opacity: 0.9; transform: translate(3px, -1px); clip-path: inset(60% 0 8% 0); }
    95% { opacity: 0.9; transform: translate(-2px, 0); clip-path: inset(35% 0 35% 0); }
}

@keyframes rad-fx-glitch-b {
    0%, 88%, 100% { opacity: 0; transform: none; clip-path: none; }
    89% { opacity: 0.9; transform: translate(3px, -1px); clip-path: inset(55% 0 15% 0); }
    92% { opacity: 0.9; transform: translate(-3px, 1px); clip-path: inset(5% 0 70% 0); }
    95% { opacity: 0.9; transform: translate(2px, 0); clip-path: inset(40% 0 30% 0); }
}

@media (prefers-reduced-motion: reduce) {
    .rad-fx-glitch-layer { animation: none; opacity: 0; }
}

[data-rad-fx-motion='reduce'] .rad-fx-glitch-layer { animation: none; opacity: 0; }
